using System.Collections.Immutable;
using System.Text;

namespace Macaron.DependencyInjection.Generator;

internal static class FactoriesRenderer
{
    internal static string Render(ImmutableArray<FactoryDefinition> definitions)
    {
        var source = new StringBuilder();

        source.AppendLine(
            """
            // <auto-generated />
            #nullable enable

            namespace Macaron.DependencyInjection.Generated
            {
                internal static class Factories
                {
                    private static readonly global::System.Collections.Frozen.FrozenDictionary<global::System.Type, global::System.Delegate> _factories;

                    static Factories()
                    {
            """
        );
        source.AppendLine($"            var factories = new global::System.Collections.Generic.Dictionary<global::System.Type, global::System.Delegate>(capacity: {definitions.Length});");

        for (var i = 0; i < definitions.Length; i++)
        {
            var typeName = definitions[i].TypeName;

            source.AppendLine($"            factories.Add(typeof({typeName}), (global::Macaron.DependencyInjection.DependencyFactory<{typeName}>)Create{i});");
        }

        source.AppendLine(
            """

                        _factories = global::System.Collections.Frozen.FrozenDictionary.ToFrozenDictionary(factories);
                    }

                    internal static global::Macaron.DependencyInjection.DependencyFactory<T> Get<T>()
                        where T : notnull
                    {
                        return (global::Macaron.DependencyInjection.DependencyFactory<T>)_factories[typeof(T)];
                    }
            """
        );

        for (var i = 0; i < definitions.Length; i++)
        {
            var factory = definitions[i];

            source.AppendLine();
            source.AppendLine($"        private static {factory.TypeName} Create{i}(");
            source.AppendLine("            global::Macaron.DependencyInjection.IDependencyResolver resolver,");
            source.AppendLine("            ref global::Macaron.DependencyInjection.CleanupCollector collector)");
            source.AppendLine("        {");
            source.AppendLine($"            return {factory.CreationExpression};");
            source.AppendLine("        }");
        }

        source.AppendLine("    }");
        source.AppendLine("}");

        return source.ToString();
    }
}
